{noformat}import {argv} from "./argv";
import {ElasticSearchClient} from "./ElasticSearchClient";

async function main() {
    const client = new ElasticSearchClient(argv.host);
    for await (const {query: {additional_params}} of client.search(argv.index, argv.columns, argv.query, argv.page_size, argv.max_rows)) {
        const text = String(additional_params).split("\n");
        const paymentUserId = text.find((l) => l.startsWith("operation.payment_user_id"))?.split(" ")[1];
        const paymentMethodToken = text.find((l) => l.startsWith("operation.payment_method_token"))?.split(" ")[1];
        if (paymentUserId && paymentMethodToken) {
            console.log(`${paymentUserId},${paymentMethodToken}`);
        }
    }
}

main().catch(err => {
    console.error(err.stack);
    process.exit(1);
});{noformat}

