{noformat}----------------------------------------------------------------------------------------------------
connection: "presto"
view: provider_weekly_admin_report {
  derived_table: {
    sql:
      select
        from_agent_id as provider_id,
        CAST(date_parse(CAST(substring(split(invoice_external_id, '-')[4], 2,4) AS varchar) || ':' || CAST(split(invoice_external_id, 'w')[2] AS varchar), '%x:%v') AS date) as period_end_week,
        'https://delivery-admin.bolt.eu/delivery/Provider/weeklyReportRedirect?id=' ||
        cast(from_agent_id as varchar) || '&period=' || split(invoice_external_id, '-')[4] ||
        '&language=' || ascl.language_code  || '&agent_type=delivery_provider&country=' || asc2.country_code  || '&format=pdf' as report_url
from glue.ng_delivery.delivery_invoicing_record dir
left join glue.ng_public.admin_system_city asc2 on asc2.id = dir.city_id
left join glue.ng_public.admin_system_country_language ascl on ascl.country_code = asc2.country_code and ascl.is_default = true
  where from_agent_type = 'delivery_provider'
  and invoice_external_id like '%-delivery_provider-%'
  and created >= cast('2021-11-22' as date) --logic differs before this date
group by 1,2,3
  ;;}

  dimension: provider_id {
    type: number
    primary_key: yes
    sql: ${TABLE}.provider_id ;;
  }

  dimension: report_url {
    type: string
    description: "Report Link PDF"
    sql: ${TABLE}.report_url ;;
    html: <a target="_blank" href={{ report_url }}><button>Report PDF Link</button></a>;;
  }

  dimension_group: period_end_week {
    type: time
    timeframes: [date, week, month, year]
    sql: ${TABLE}.period_end_week ;;
  }

  measure: count {
    type: count_distinct
    sql:  ${report_url};;
    label: "Count of Invoices"
  }
}
